package org.apache.commons.csv;

import java.io.StringReader;
import java.nio.charset.StandardCharsets;

public class Probe {
    public static void main(String[] args) throws Exception {
        ExtendedBufferedReader r = new ExtendedBufferedReader(new StringReader(""));
        char[] buf = new char[5];
        int n = r.read(buf, 0, 5);
        System.out.println("read at EOF returns=" + n + " position=" + r.getPosition() + " lastChar=" + r.getLastChar());

        ExtendedBufferedReader r2 = new ExtendedBufferedReader(new StringReader("ab"));
        char[] b2 = new char[5];
        int n2 = r2.read(b2, 0, 5);
        System.out.println("short read n2=" + n2 + " position=" + r2.getPosition() + " content=" + new String(b2,0,n2));

        // peek beyond available
        ExtendedBufferedReader r3 = new ExtendedBufferedReader(new StringReader("ab"));
        char[] p = new char[5];
        int pn = r3.peek(p);
        System.out.println("peek pn=" + pn + " position after peek=" + r3.getPosition());
        int rc = r3.read();
        System.out.println("read after peek=" + (char) rc + " position=" + r3.getPosition());

        // peek empty array
        ExtendedBufferedReader r4 = new ExtendedBufferedReader(new StringReader("ab"));
        System.out.println("peek empty=" + r4.peek(new char[0]));

        // mark/reset
        ExtendedBufferedReader r5 = new ExtendedBufferedReader(new StringReader("a\nb"));
        r5.read(); // 'a'
        r5.mark(10);
        r5.read(); // '\n'
        System.out.println("lineNumber after \\n=" + r5.getLineNumber() + " pos=" + r5.getPosition());
        r5.reset();
        System.out.println("after reset lineNumber=" + r5.getLineNumber() + " pos=" + r5.getPosition() + " lastChar=" + r5.getLastChar());

        // bytes UTF8
        ExtendedBufferedReader r6 = new ExtendedBufferedReader(new StringReader("aé"), StandardCharsets.UTF_8, true);
        r6.read();
        System.out.println("bytesRead after 'a'=" + r6.getBytesRead());
        r6.read();
        System.out.println("bytesRead after 'e9'=" + r6.getBytesRead());

        // bytes UTF16
        ExtendedBufferedReader r7 = new ExtendedBufferedReader(new StringReader("ab"), StandardCharsets.UTF_16, true);
        r7.read();
        System.out.println("UTF16 bytesRead after 'a'=" + r7.getBytesRead());
        r7.read();
        System.out.println("UTF16 bytesRead after 'b'=" + r7.getBytesRead());

        // surrogate pair bytes UTF8 (emoji U+1F600)
        String emoji = new String(Character.toChars(0x1F600));
        ExtendedBufferedReader r8 = new ExtendedBufferedReader(new StringReader(emoji), StandardCharsets.UTF_8, true);
        int c1 = r8.read();
        System.out.println("high surrogate read=" + c1 + " bytesRead=" + r8.getBytesRead());
        int c2 = r8.read();
        System.out.println("low surrogate read=" + c2 + " bytesRead=" + r8.getBytesRead());
        byte[] expectedBytes = emoji.getBytes(StandardCharsets.UTF_8);
        System.out.println("expected total bytes=" + expectedBytes.length);

        // close then read
        ExtendedBufferedReader r9 = new ExtendedBufferedReader(new StringReader("ab"));
        r9.close();
        System.out.println("lastChar after close=" + r9.getLastChar());
        try {
            r9.read();
            System.out.println("no exception on read after close");
        } catch (Exception e) {
            System.out.println("exception on read after close: " + e.getClass().getName());
        }

        // readLine
        ExtendedBufferedReader r10 = new ExtendedBufferedReader(new StringReader("line1\r\nline2\nline3"));
        System.out.println("readLine1=" + r10.readLine() + " lineNumber=" + r10.getLineNumber());
        System.out.println("readLine2=" + r10.readLine() + " lineNumber=" + r10.getLineNumber());
        System.out.println("readLine3=" + r10.readLine() + " lineNumber=" + r10.getLineNumber());
        System.out.println("readLine4=" + r10.readLine());

        // getLineNumber initial and single char
        ExtendedBufferedReader r11 = new ExtendedBufferedReader(new StringReader("abc"));
        System.out.println("initial lineNumber=" + r11.getLineNumber());
        r11.read();
        System.out.println("lineNumber after reading 'a'=" + r11.getLineNumber());

        // CR LF sequence counting
        ExtendedBufferedReader r12 = new ExtendedBufferedReader(new StringReader("a\r\nb"));
        r12.read(); r12.read(); // a, \r
        System.out.println("lineNumber after CR=" + r12.getLineNumber());
        r12.read(); // \n
        System.out.println("lineNumber after CRLF=" + r12.getLineNumber());

        // EOF at end, line number
        ExtendedBufferedReader r13 = new ExtendedBufferedReader(new StringReader("a"));
        r13.read();
        System.out.println("lineNumber after 'a' (no eol yet)=" + r13.getLineNumber());
        r13.read(); // EOF
        System.out.println("lineNumber after EOF with no eol=" + r13.getLineNumber() + " lastChar=" + r13.getLastChar());
    }
}
